struct DenyByDefault: AsyncMiddleware {
    let policy: Policy
    func respond(to req: Request, chainingTo next: AsyncResponder) async throws -> Response {
        guard let user = req.auth.get(User.self),
              let grant = await policy.grant(for: user, req) else {
            throw Abort(.forbidden)                 // no identity or no grant -> deny
        }
        req.storage[GrantKey.self] = grant
        return try await next.respond(to: req)
    }
}
app.middleware.use(DenyByDefault(policy: policy))   // before route groups are added
